// frontend/src/pages/BackupStrategy.js
// Pure vertical layout — no horizontal overflow anywhere

export default function BackupStrategy() {

  // ── PRIMITIVES ─────────────────────────────────────────────────────────────

  const Tag = ({ children, color = 'blue' }) => {
    const C = {
      blue:   ['var(--bv-blue-dim)',   'var(--bv-blue)'  ],
      green:  ['var(--bv-green-bg)',   'var(--bv-green)' ],
      amber:  ['var(--bv-amber-bg)',   'var(--bv-amber)' ],
      red:    ['var(--bv-red-bg)',     'var(--bv-red)'   ],
      cyan:   ['var(--bv-cyan-bg)',    'var(--bv-cyan)'  ],
      purple: ['var(--bv-purple-bg)',  'var(--bv-purple)'],
    };
    const [bg, txt] = C[color] || C.blue;
    return (
      <span style={{ fontSize:10, padding:'2px 9px', borderRadius:10, fontWeight:600,
        background:bg, color:txt, whiteSpace:'nowrap', flexShrink:0 }}>
        {children}
      </span>
    );
  };

  // Vertical down-arrow
  const Down = ({ label, color = 'var(--bv-bd2)', len = 28 }) => (
    <div style={{ display:'flex', flexDirection:'column', alignItems:'center', margin:'2px 0', gap:2, alignSelf:'flex-start', marginLeft:20 }}>
      <div style={{ width:2, height:len, background:color, borderRadius:1 }} />
      <div style={{ width:0, height:0,
        borderLeft:'5px solid transparent', borderRight:'5px solid transparent',
        borderTop:`7px solid ${color}` }} />
      {label && <div style={{ fontSize:10, color:'var(--bv-txt3)', marginTop:2, textAlign:'center' }}>{label}</div>}
    </div>
  );

  // Info box
  const Info = ({ children, color = 'blue' }) => {
    const C = {
      blue:  ['var(--bv-blue-dim)',  'var(--bv-blue)' ],
      green: ['var(--bv-green-bg)',  'var(--bv-green)'],
      amber: ['var(--bv-amber-bg)',  'var(--bv-amber)'],
      red:   ['var(--bv-red-bg)',    'var(--bv-red)'  ],
    };
    const [bg, bd] = C[color] || C.blue;
    return (
      <div style={{ padding:'9px 13px', background:bg, border:`1px solid ${bd}`,
        borderRadius:8, fontSize:11.5, color:'var(--bv-txt)', lineHeight:1.7 }}>
        {children}
      </div>
    );
  };

  // Block: full-width card
  const Block = ({ icon, title, items = [], color = 'blue', badge, right }) => {
    const C = {
      blue:   ['var(--bv-blue-dim)',   'var(--bv-blue)'  ],
      green:  ['var(--bv-green-dim)',  'var(--bv-green)' ],
      amber:  ['var(--bv-amber-bg)',   'var(--bv-amber)' ],
      red:    ['var(--bv-red-bg)',     'var(--bv-red)'   ],
      cyan:   ['var(--bv-cyan-bg)',    'var(--bv-cyan)'  ],
      purple: ['var(--bv-purple-bg)', 'var(--bv-purple)'],
    };
    const [bg, bd] = C[color] || C.blue;
    return (
      <div style={{ background:bg, border:`1.5px solid ${bd}`, borderRadius:10,
        padding:'10px 14px', width:'100%', boxSizing:'border-box',
        display:'flex', alignItems:'flex-start', justifyContent:'space-between', gap:12 }}>
        <div style={{ flex:1 }}>
          <div style={{ display:'flex', alignItems:'center', gap:8, marginBottom: items.length ? 7 : 0 }}>
            {badge && <span style={{ fontSize:9, background:bd, color:'#fff',
              padding:'1px 6px', borderRadius:3, fontWeight:700, flexShrink:0 }}>{badge}</span>}
            <i className={`ti ti-${icon}`} style={{ fontSize:16, color:bd, flexShrink:0 }}/>
            <span style={{ fontSize:12, fontWeight:600, color:bd, lineHeight:1.3 }}>{title}</span>
          </div>
          {items.map((it, i) => (
            <div key={i} style={{ fontSize:11, color:'var(--bv-txt2)', lineHeight:1.7,
              paddingLeft:25, position:'relative' }}>
              <span style={{ position:'absolute', left:11, color:bd }}>·</span>
              {it}
            </div>
          ))}
        </div>
        {right && <div style={{ flexShrink:0 }}>{right}</div>}
      </div>
    );
  };

  // Two-column grid row (50/50, no overflow)
  const TwoCol = ({ left, right, leftLabel, rightLabel }) => (
    <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:12 }}>
      <div>
        {leftLabel && <div style={{ fontSize:10, fontWeight:600, color:'var(--bv-txt3)',
          textTransform:'uppercase', letterSpacing:'.07em', marginBottom:8 }}>{leftLabel}</div>}
        {left}
      </div>
      <div>
        {rightLabel && <div style={{ fontSize:10, fontWeight:600, color:'var(--bv-txt3)',
          textTransform:'uppercase', letterSpacing:'.07em', marginBottom:8 }}>{rightLabel}</div>}
        {right}
      </div>
    </div>
  );

  // Four-column grid
  const FourCol = ({ children }) => (
    <div style={{ display:'grid', gridTemplateColumns:'repeat(4,1fr)', gap:10 }}>{children}</div>
  );

  // Step section
  const Step = ({ n, title, bgColor, children }) => (
    <div style={{ border:'1px solid var(--bv-bd)', borderRadius:12,
      overflow:'hidden', marginBottom:12 }}>
      <div style={{ padding:'10px 18px', background: bgColor || 'var(--bv-bg3)',
        borderBottom:'1px solid var(--bv-bd)',
        display:'flex', alignItems:'center', gap:12 }}>
        <div style={{ width:26, height:26, borderRadius:'50%', background:'var(--bv-accent)',
          color:'#fff', fontSize:12, fontWeight:700,
          display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 }}>{n}</div>
        <span style={{ fontSize:13, fontWeight:600, color:'var(--bv-txt)' }}>{title}</span>
      </div>
      <div style={{ padding:16, background:'var(--bv-card)',
        display:'flex', flexDirection:'column', gap:10 }}>
        {children}
      </div>
    </div>
  );

  // Sequence step — numbered inline
  const Seq = ({ n, icon, title, detail, color = 'blue', tag }) => {
    const C = {
      blue:   'var(--bv-blue)',   green: 'var(--bv-green)',
      amber:  'var(--bv-amber)',  red:   'var(--bv-red)',
      cyan:   'var(--bv-cyan)',   purple:'var(--bv-purple)',
    };
    const col = C[color] || C.blue;
    return (
      <div style={{ display:'flex', alignItems:'flex-start', gap:12,
        padding:'9px 12px', background:'var(--bv-bg3)',
        border:'1px solid var(--bv-bd)', borderRadius:9 }}>
        <div style={{ width:24, height:24, borderRadius:'50%', background:col, color:'#fff',
          fontSize:11, fontWeight:700, display:'flex', alignItems:'center',
          justifyContent:'center', flexShrink:0 }}>{n}</div>
        <i className={`ti ti-${icon}`} style={{ fontSize:16, color:col, flexShrink:0, marginTop:3 }}/>
        <div style={{ flex:1 }}>
          <div style={{ fontSize:12, fontWeight:600, color:col }}>{title}</div>
          {detail && <div style={{ fontSize:11, color:'var(--bv-txt2)', lineHeight:1.6, marginTop:2 }}>{detail}</div>}
        </div>
        {tag && <Tag color={color}>{tag}</Tag>}
      </div>
    );
  };

  // Rule row
  const Rule = ({ n, text, tag, tagColor = 'blue' }) => (
    <div style={{ display:'flex', alignItems:'flex-start', gap:10, padding:'8px 0',
      borderBottom:'1px solid var(--bv-bd)' }}>
      <div style={{ width:20, height:20, borderRadius:'50%', background:'var(--bv-blue-dim)',
        color:'var(--bv-blue)', fontSize:10, fontWeight:700,
        display:'flex', alignItems:'center', justifyContent:'center',
        flexShrink:0, marginTop:1 }}>{n}</div>
      <div style={{ flex:1, fontSize:12, color:'var(--bv-txt2)', lineHeight:1.5 }}>{text}</div>
      <Tag color={tagColor}>{tag}</Tag>
    </div>
  );

  const DBRow = ({ name, type, addr }) => {
    const ic = { MySQL:'M', PostgreSQL:'P', Redis:'R' };
    const bg = { MySQL:'#1e3a1e', PostgreSQL:'#1a2550', Redis:'#3d1a10' };
    const cl = { MySQL:'#4ec94e', PostgreSQL:'#7ca8f8', Redis:'#f85149' };
    return (
      <div style={{ display:'flex', alignItems:'center', gap:9, padding:'7px 11px',
        background:'var(--bv-blue-dim)', border:'1px solid var(--bv-blue)',
        borderRadius:8, marginBottom:5 }}>
        <div style={{ width:22, height:22, borderRadius:5, background:bg[type]||'#222',
          color:cl[type]||'#fff', fontSize:9, fontWeight:700,
          display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0 }}>
          {ic[type]||'?'}
        </div>
        <div style={{ flex:1 }}>
          <div style={{ fontSize:12, fontWeight:500, color:'var(--bv-blue)' }}>{name} ({type})</div>
          <div style={{ fontSize:10, color:'var(--bv-txt3)', fontFamily:'monospace' }}>{addr}</div>
        </div>
        <div style={{ width:6, height:6, borderRadius:'50%', background:'var(--bv-green)' }}/>
      </div>
    );
  };

  // ── PAGE ─────────────────────────────────────────────────────────────────

  return (
    <div style={{ flex:1, display:'flex', flexDirection:'column', overflow:'hidden' }}>

      {/* Header */}
      <div style={{ padding:'14px 22px 12px', borderBottom:'1px solid var(--bv-bd)',
        background:'var(--bv-bg2)', flexShrink:0 }}>
        <div style={{ fontSize:20, fontWeight:500, color:'var(--bv-txt)' }}>
          <i className="ti ti-sitemap" style={{ marginRight:9, color:'var(--bv-blue)' }}/>
          Backup Strategy & Flow
        </div>
        <div style={{ fontSize:12, color:'var(--bv-txt2)', marginTop:3 }}>
          End-to-end backup pipeline — from live DB servers to multi-tier disaster recovery
        </div>
      </div>

      <div style={{ flex:1, overflowY:'auto', padding:'16px 22px', display:'flex', flexDirection:'column', gap:0 }}>

        {/* ── OVERVIEW PIPELINE ─────────────────────────────── */}
        <div style={{ border:'1px solid var(--bv-bd)', borderRadius:12, overflow:'hidden', marginBottom:14 }}>
          <div style={{ padding:'9px 16px', background:'var(--bv-bg3)',
            borderBottom:'1px solid var(--bv-bd)',
            fontSize:11, fontWeight:600, color:'var(--bv-txt2)',
            letterSpacing:'.06em', textTransform:'uppercase' }}>
            Complete backup pipeline overview
          </div>
          <div style={{ padding:'16px', background:'var(--bv-card)' }}>
            <div style={{ display:'flex', flexDirection:'column', gap:6 }}>
              {[
                { icon:'database',      label:'5 Live DB Servers',         sub:'MySQL · PostgreSQL · Redis',             color:'var(--bv-blue)',   bg:'var(--bv-blue-dim)' },
                { arrow: true, label:'mysqldump | gzip' },
                { icon:'device-floppy', label:'Primary DC (NFS · 10.180.0.90)', sub:'/primary-db-backup · 482G pool',      color:'var(--bv-green)',  bg:'var(--bv-green-dim)' },
                { arrow: true, label:'when > 80% · manual admin action' },
                { icon:'server-2',      label:'Secondary DC (10.180.0.130)',sub:'/secondary-db-backup · long-term archive', color:'var(--bv-cyan)',   bg:'var(--bv-cyan-bg)' },
                { arrow: true, label:'incremental rsync over SSH (automated)' },
                { icon:'building',      label:'Remote Onsite DR (192.168.12.243)', sub:'/backups/remote · 1TB pool',       color:'var(--bv-amber)',  bg:'var(--bv-amber-bg)' },
                { arrow: true, label:'on-demand from dashboard' },
                { icon:'brand-aws',     label:'AWS S3 (ap-south-1 Mumbai)',  sub:'s3://worktual-db-backups · STANDARD_IA', color:'var(--bv-purple)', bg:'var(--bv-purple-bg)' },
              ].map((item, i) => item.arrow ? (
                <div key={i} style={{ display:'flex', alignItems:'center', gap:10, paddingLeft:20 }}>
                  <div style={{ display:'flex', flexDirection:'column', alignItems:'center', gap:0 }}>
                    <div style={{ width:2, height:22, background:'var(--bv-bd2)' }}/>
                    <div style={{ width:0, height:0, borderLeft:'4px solid transparent',
                      borderRight:'4px solid transparent', borderTop:'6px solid var(--bv-bd2)' }}/>
                  </div>
                  <span style={{ fontSize:10.5, color:'var(--bv-txt3)', fontStyle:'italic' }}>{item.label}</span>
                </div>
              ) : (
                <div key={i} style={{ display:'flex', alignItems:'center', gap:12,
                  padding:'9px 14px', background:item.bg,
                  border:`1.5px solid ${item.color}`, borderRadius:9 }}>
                  <i className={`ti ti-${item.icon}`} style={{ fontSize:20, color:item.color, flexShrink:0 }}/>
                  <div>
                    <div style={{ fontSize:12, fontWeight:600, color:item.color }}>{item.label}</div>
                    <div style={{ fontSize:10.5, color:'var(--bv-txt3)', marginTop:1 }}>{item.sub}</div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* ── STEP 1 ─────────────────────────────────────────── */}
        <Step n="1" title="Daily Scheduled Backup — 03:00 IST (Rule 1)" bgColor="var(--bv-blue-dim)">
          <div style={{ fontSize:11, fontWeight:600, color:'var(--bv-txt3)',
            textTransform:'uppercase', letterSpacing:'.06em', marginBottom:4 }}>
            Source — 5 live DB servers
          </div>
          {[
            ['DB-Node-1','MySQL',      '10.180.0.201:3306'],
            ['DB-Node-2','MySQL',      '10.180.0.202:3306'],
            ['DB-Node-3','PostgreSQL', '10.180.0.203:5432'],
            ['DB-Node-4','PostgreSQL', '10.180.0.204:5432'],
            ['DB-Node-5','Redis',      '10.180.0.205:6379'],
          ].map(([name,type,addr]) => (
            <DBRow key={name} name={name} type={type} addr={addr}/>
          ))}
          <Down label="mysqldump | gzip" color="var(--bv-blue)"/>
          <Block icon="terminal-2" title='bash -c "mysqldump ... | gzip > file.sql.gz"' color="blue"
            items={[
              'Options: --single-transaction --routines --triggers --events',
              'gzip -t integrity check after dump — rejects if file < 1 KB',
              'PostgreSQL uses pg_dump -Fc, Redis uses BGSAVE + RDB copy',
            ]}/>
          <Down label="stored as" color="var(--bv-green)"/>
          <Block icon="device-floppy" title="Primary DC — /primary-db-backup/<db>/Backup_DB/<YYYYMMDD>/" color="green"
            items={[
              '482G NFS pool on 10.180.0.90',
              'Cron schedule: 0 3 * * * (every night at 03:00 IST)',
              'All 5 DB servers backed up sequentially',
            ]}/>
          <Info color="blue">
            <strong>Schedule:</strong> <code style={{ fontFamily:'monospace', color:'var(--bv-cyan)' }}>0 3 * * *</code> — runs every night at 03:00 IST. Each DB gets its own folder. File naming: <code style={{ fontFamily:'monospace', color:'var(--bv-cyan)', fontSize:10 }}>mysql_&lt;db&gt;_full_2026-06-27_03-00-00.sql.gz</code>
          </Info>
        </Step>

        {/* ── STEP 2 ─────────────────────────────────────────── */}
        <Step n="2" title="Primary DC 80% Threshold — Rule 2 (Currently Active at 87%)" bgColor="var(--bv-amber-bg)">
          <Block icon="chart-bar" title="Disk monitor — checks every 30 minutes" color="amber"
            items={[
              'Runs df on /primary-db-backup every 30 minutes',
              'Alert threshold: 80% → email all admins + dashboard badge',
              'Critical threshold: 90% → block new backup jobs',
            ]}/>
          <Down label="≥ 80% detected" color="var(--bv-amber)"/>
          <Block icon="bell" title="Admin notification sent" color="amber"
            items={[
              'Email sent to all users in the users table',
              'Dashboard shows "Rule 2: Active Now" badge on Primary DC',
              'Active alert panel shows with timestamp',
            ]}/>
          <Down label="admin manually runs copy" color="var(--bv-txt3)"/>

          {/* 4-step sequence — vertical */}
          <div style={{ padding:'12px 14px', background:'var(--bv-bg3)',
            borderRadius:9, border:'1px solid var(--bv-bd)',
            display:'flex', flexDirection:'column', gap:8 }}>
            <div style={{ fontSize:11, fontWeight:600, color:'var(--bv-txt2)',
              textTransform:'uppercase', letterSpacing:'.06em', marginBottom:4 }}>
              Manual copy sequence: Primary DC → Secondary DC
            </div>
            <Seq n="①" icon="search" color="amber" title="Identify old files"
              detail="Find all date folders older than 50 days in /primary-db-backup/<db>/Backup_DB/"/>
            <Seq n="②" icon="server-2" color="cyan" title="Copy to Secondary DC (10.180.0.130)"
              detail="rsync --checksum to /secondary-db-backup/ — same db/Backup_DB/YYYYMMDD/ structure preserved"/>
            <Seq n="③" icon="check" color="green" title="Verify copy integrity"
              detail="File size match + gzip -t integrity check + md5sum comparison on both sides"/>
            <Seq n="④" icon="trash" color="red" title="Delete from Primary DC (only if ③ passed)"
              detail="rm -rf the old date folder from /primary-db-backup. Logged with timestamp in audit trail."/>
          </div>

          <Info color="red">
            <i className="ti ti-shield-lock" style={{ marginRight:6, color:'var(--bv-red)' }}/>
            <strong>Safety rule:</strong> Files are <strong>NEVER</strong> deleted from Primary DC unless Secondary DC copy passes both size check and gzip integrity check. Copy failure → file stays in Primary DC and error is logged.
          </Info>
        </Step>

        {/* ── STEP 3 ─────────────────────────────────────────── */}
        <Step n="3" title="Incremental Backup → Remote Onsite DR — Rule 3 (Automated)" bgColor="var(--bv-green-dim)">
          <Block icon="device-floppy" title="Primary DC — detects new files since last sync" color="green"
            items={[
              'rsync --checksum compares file hashes — only transfers changed blocks',
              'Triggered automatically after each Rule 1 daily backup completes',
              'Also triggered by on-demand backups (Rule 4)',
            ]}/>
          <Down label="rsync over SSH · sshpass · port 22" color="var(--bv-green)"/>
          <Block icon="building" title="Remote Onsite DR — 192.168.12.243 · /backups/remote" color="amber"
            items={[
              'Same folder structure: /backups/remote/<db>/Backup_DB/<YYYYMMDD>/',
              '1TB pool · 52% used · SFTP browser available in portal',
              'Both sides always contain identical files after sync completes',
            ]}/>
          <Info color="green">
            <strong>Recovery:</strong> Any backup file can be downloaded directly from the portal via <em>Remote Onsite → SFTP File Explorer</em>. No SSH access needed.
          </Info>
        </Step>

        {/* ── STEP 4 ─────────────────────────────────────────── */}
        <Step n="4" title="On-Demand Backup from Dashboard — Rule 4 (Manual trigger)" bgColor="var(--bv-blue-bg)">
          <Block icon="player-play" title="Dashboard → Start Backup button" color="blue"
            items={[
              'Select target: single DB server OR All Targets at once',
              'Select type: Full Backup or Incremental',
              'Live progress shown in WebSocket log panel (Live Logs page)',
            ]}/>
          <Down label="transfers to all active destinations" color="var(--bv-blue)"/>
          <Seq n="①" icon="device-floppy" color="green" title="Primary DC — always included"
            detail="/primary-db-backup/<db>/Backup_DB/<date>/ — first destination, always active"/>
          <Seq n="②" icon="building" color="amber" title="Remote Onsite — rsync via SSH"
            detail="rsync to 192.168.12.243:/backups/remote/ — same structure, SSH + sshpass"/>
          <Seq n="③" icon="brand-aws" color="purple" title="AWS S3 — only if enabled"
            detail="aws s3 cp to s3://worktual-db-backups/db-backups/<db>/ — skipped if destination is inactive"/>
        </Step>

        {/* ── STEP 5 ─────────────────────────────────────────── */}
        <Step n="5" title="AWS S3 Cloud Backup — ap-south-1 Mumbai (On-Demand + Lifecycle)" bgColor="var(--bv-purple-bg)">
          <Block icon="brand-aws" title="S3 STANDARD_IA — s3://worktual-db-backups/" color="purple"
            items={[
              'Region: ap-south-1 (Mumbai) · Storage class: STANDARD_IA',
              'Infrequent access pricing · Immediate restore available',
              'Uploads triggered by on-demand backup (Rule 4) or scheduled jobs',
            ]}/>
          <Down label="automatic lifecycle policy after 90 days" color="var(--bv-txt3)"/>
          <Block icon="snowflake" title="S3 Glacier Deep Archive — auto-transition after 90 days" color="cyan"
            items={[
              'Long-term cold storage · lowest cost per GB',
              'Restore time: 12 hours (Glacier) or 48 hours (Deep Archive)',
              'Lifecycle rule configured in S3 bucket policy — no manual action needed',
            ]}/>
        </Step>

        {/* ── STEP 6 ─────────────────────────────────────────── */}
        <Step n="6" title="Retention Policy by Storage Tier" bgColor="var(--bv-bg3)">
          <FourCol>
            {[
              { icon:'device-floppy', title:'Primary DC',    color:'green',  policy:'Latest 50 days',     detail:'Older files moved to Secondary DC when disk > 80%. Auto-cleanup after verified copy.' },
              { icon:'server-2',      title:'Secondary DC',  color:'cyan',   policy:'Long-term archive',  detail:'Manual copies from Primary DC (Rule 2). No auto-delete. Kept indefinitely.' },
              { icon:'building',      title:'Remote Onsite', color:'amber',  policy:'Mirror of Primary',  detail:'Incremental sync after each backup run. Same date range as Primary DC always.' },
              { icon:'brand-aws',     title:'AWS S3',        color:'purple', policy:'90 days → Glacier',  detail:'STANDARD_IA for 90 days, then auto-transitioned to Glacier Deep Archive.' },
            ].map(r => (
              <div key={r.title} style={{ background:'var(--bv-bg3)', border:'1px solid var(--bv-bd)', borderRadius:10, padding:12 }}>
                <Block icon={r.icon} title={r.title} color={r.color}/>
                <div style={{ marginTop:8, padding:'8px 10px', background:'var(--bv-card)',
                  borderRadius:7, border:'1px solid var(--bv-bd)' }}>
                  <div style={{ fontSize:11, fontWeight:600, color:'var(--bv-txt)', marginBottom:3 }}>{r.policy}</div>
                  <div style={{ fontSize:11, color:'var(--bv-txt2)', lineHeight:1.5 }}>{r.detail}</div>
                </div>
              </div>
            ))}
          </FourCol>
        </Step>

        {/* ── STEP 7 ─────────────────────────────────────────── */}
        <Step n="7" title="Monitoring & Notifications — Rules 5 & 6" bgColor="var(--bv-bg3)">
          <TwoCol
            leftLabel="Automated monitoring (Rule 5)"
            left={<>
              <Rule n="5a" text="Every 30 min: check disk usage on Primary DC, Secondary DC, Remote Onsite — alert at 80%, block at 90%" tag="Auto" tagColor="blue"/>
              <Rule n="5b" text="Every 15 min: test AWS S3 connectivity — auto-deactivate destination if bucket unreachable or credentials fail" tag="Auto" tagColor="blue"/>
              <Rule n="5c" text="DB server reachability check before each backup job — skip and log if server offline, continue with others" tag="Auto" tagColor="blue"/>
            </>}
            rightLabel="Email notifications (Rule 6)"
            right={<>
              <Rule n="6a" text="Immediate email when any backup job fails or transfer errors — sent to all users in users table" tag="Email" tagColor="red"/>
              <Rule n="6b" text="Email when Primary DC or Remote Onsite disk exceeds 80% threshold — triggers Rule 2 manual action" tag="Email" tagColor="amber"/>
              <Rule n="6c" text="Daily summary email at 09:00 IST: total runs, success rate, GB transferred, failed jobs list" tag="Email" tagColor="green"/>
            </>}
          />
        </Step>

      </div>
    </div>
  );
}
